B.cQI=new A.p("containsType",B.E,"Edge type value meaning containment (default contains).",B.f,null)
B.cMD=new A.p("projectType",B.E,"typeColumn value marking a project/owner ancestor (default group).",B.f,null)
B.cY7=new A.p("recencyColumns",B.V,'Ordered timestamp columns checked to find the Now lane\'s "in motion" row per project group (default [postedAt, editedAt]).',B.f,null)
