B.cVa=new A.p("snapMaxKm",B.af,'Max straight-line distance (km) a pin may snap to the nearest routing node (default 1.5). Beyond this, that leg reports an honest "no nearby station" state instead of a fabricated route.',B.f,null)
B.cPV=new A.p("routeColor",B.E,"Highlighted route-overlay polyline color (default: theme error color) \u2014 visually distinct from any static line sourceLayers.",B.f,null)
B.cWP=new A.p("routeWidth",B.af,"Route-overlay polyline stroke width (default 4).",B.f,null)
