B.cZO=new A.p("rotationColumn",B.t,'Optional rotation in degrees (default "rotation").',B.f,null)
B.cN5=new A.p("flipOnTap",B.W,"Tap flips the item (default true; false for fixed tokens).",B.f,null)
B.cVm=new A.p("flick",B.af,"Momentum carried from a flick; 0 = none (default 0.12).",B.f,null)
B.cKr=new A.p("itemWidth",B.af,"Item width in px (default 76).",B.f,null)
