B.cwB=new A.d1("tabletop","A free-form felt table: items (cards, tokens, notes) projected from a table of rows, each freely dragged, flicked, and flipped ANYWHERE \u2014 like loose objects on a real table. NO rules are enforced; a tap flips, a drag moves, and every move commits x/y/z so it syncs live to all players.",B.bkb,!1)
B.cHc=new A.p("table",B.at,"Cards table (one row per card).",B.f,null)
B.cZt=new A.p("pileColumn",B.t,'Group cards into piles by this column (default "holder").',B.f,null)
B.cKd=new A.p("orderColumn",B.t,'Order within a pile (default "order").',B.f,null)
B.cIN=new A.p("rankColumn",B.t,'Rank column: a label like "A"/"10"/"K" (default "rank").',B.f,null)
B.cNn=new A.p("suitColumn",B.t,'Suit column: \u2660\u2665\u2666\u2663, an index 0..3, or S/H/D/C (default "suit").',B.f,null)
B.cSs=new A.p("faceColumn",B.t,'Bool; false renders the card back (default "faceUp").',B.f,null)
B.cWX=new A.p("labelColumn",B.t,'Fallback face text if rank is empty (default "label").',B.f,null)
