B.cWK=new A.p("layout",B.bF,"Layout: piles/fan stacks; grid = a centered wrapping tableau.",B.bzR,null)
B.cYH=new A.p("filter",B.V,"Optional node-local filter {column, value} or {column, in:[...]}.",B.f,null)
B.d_A=new A.p("pileOrder",B.V,"Pinned pile order (a list of pileColumn values; shown even if empty).",B.f,null)
B.cGF=new A.p("pileLabels",B.V,"Map of pile value \u2192 display label.",B.f,null)
B.cVi=new A.p("cardWidth",B.af,"Card width in logical px (default 64).",B.f,null)
B.cXS=new A.p("fan",B.af,"Overlap fraction for stacked/fanned cards (default 0.18).",B.f,null)
B.cJk=new A.p("maxStack",B.af,"Max cards drawn for a stacked pile; deeper piles show top N + a count (default 6). Hands (fan) and grids are never capped.",B.f,null)
B.cXP=new A.p("fontFamily",B.E,"Font for rank/court letters (suits are vector-drawn). Default: system.",B.f,null)
B.cZP=new A.p("onTap",B.V,"Card-tap action spec { fn, args }.",B.f,null)
B.d_R=new A.p("action",B.V,"Alias for `onTap` (card-tap action spec { fn, args }); either name works.",B.f,null)
