B.cSL=new A.p("containsType",B.E,'Edges-mode: edgeType value meaning "contains" (default "contains").',B.f,null)
B.cSt=new A.p("sharedBadge",B.W,'Edges-mode: show a small "also in N" chip on a node with more than one incoming contains-edge (lives under several parents).',B.f,null)
