B.cSi=new A.p("column",B.t,'Column the typed text fills (default "text").',B.f,null)
B.cJu=new A.p("placeholder",B.E,"Empty-input hint text; may be a {lang: text} map.",B.f,null)
B.cH2=new A.p("values",B.V,"Columns preset on every sent row; values resolve $playerId/now/uuid.",B.f,null)
B.cRa=new A.p("sendIcon",B.E,"Send-button icon (send/arrow).",B.f,null)
B.cIg=new A.p("action",B.V,"Optional action fired on the new row (e.g. translate it).",B.f,null)
B.cKP=new A.p("helperAction",B.V,'Optional "compose helper" action fired on the DRAFT still in the text field (no row created) \u2014 draftText is merged into its own args. Renders a small icon button next to send ONLY when set.',B.f,null)
B.cXI=new A.p("helperIcon",B.E,"Compose-helper button icon (translate/auto_awesome/lightbulb).",B.f,null)
